```rust
use std::fs;
use std::io::{Read, Write};
use std::net::{TcpListener, TcpStream};
use std::path::Path;
use std::sync::{Arc, Mutex};
use std::thread;

#[cfg(feature = "std")]
mod std_impl {
    use std::io::{Read, Write};
    use std::net::TcpStream;
    use std::path::Path;
}

/// A simple implementation of a concurrent web server.
#[cfg(feature = "std")]
pub fn concurrent_web_server() {
    // Define the request handler.
    let mut request_handler = Arc::new(Mutex::new(CustomHandler::new()));

    // Spawn a new thread for each incoming request.
    let listener = TcpListener::bind("127.0.0.1:8080").expect("Failed to bind!");

    // Spawn a new thread for handling each incoming request.
    for stream in listener.incoming() {
        let mut request_handler = request_handler.clone();
        thread::spawn(move || {
            let mut handler = request_handler.lock().expect("Failed to lock handler.");
            // Read the request.
            let mut buffer = [0; 1024 * 4];
            stream.read(&mut buffer[..]).expect("Failed to read request.");
            let request = String::from_utf8_lossy(&buffer[..]);

            // Handle the request.
            let response = handler.handle_request(request);
            let mut buffer = [0; 1024 * 4];
            buffer[..] = response[..].as_bytes();

            // Write the response.
            stream.write(&mut buffer[..]).expect("Failed to write response.");
        });
    }
}

/// A simple custom handler for HTTP requests.
struct CustomHandler {
    fn new() -> impl Iterator<Item = Result<(Path, String), ()>> + 'static {
        (0..10).map(move |i| {
            match i {
                0..3 => Ok((Path::new("/index.html"), String::from("Hello"))),
                4..7 => Ok((Path::new("/about.html"), String::from("About"))),
                8..10 => Ok((Path::new("/error404.html"), String::from("404 Not Found"))),
                _ => Err(std::convert::ConvertError::from("Unhandled case")),
            }
        })
    }
}

/// Handles HTTP requests.
impl CustomHandler {
    fn handle_request(&self, request: String) -> Result<(Path, String), ()> {
        request.split_whitespace().next_matches().nth(1).map_or_else(
            |i| match i {
                1..10 => Ok((Path::new("/page.html"), String::from("Page"))),
                _ => Err(std::convert::ConvertError::from("Unhandled case")),
            },
            |i| match i {
                1..3 => Ok((Path::new("/index.html"), String::from("Hello"))),
                4..7 => Ok((Path::new("/about.html"), String::from("About"))),
                8..10 => Ok((Path::new("/error404.html"), String::from("404 Not Found"))),
                _ => Err(std::convert::ConvertError::from("Unhandled case")),
            }
        )
        .expect("Failed to handle request.")
    }
}

#[cfg(feature = "std")]
fn main() {
    concurrent_web_server();
}
```

