fn parse_request(buffer: &[u8; 1024]) -> (String, String, String) {
    let buffer_len = buffer.len();
    let method_len = buffer[0..buffer.len()].find(|&x| x == b' ').unwrap_or(1024);
    let path_len = buffer[0..buffer.len()].find(|&x| x == b' ').unwrap_or(1024);
