        if !self.is_valid_data(data) {
            return Err(std::io::Error::new(std::io::ErrorKind::InvalidInput, "Invalid request data"));
        }

        // Handle the request, e.g., write the response
        stream.write_all(format!("{} - Hello from {}!", data, self.listener.local_addr()).as_bytes());
        Ok(())
    }

    fn start_server(&self) {
        if self.running.load(false) {
            return; // Already running
        }

        // Start the server
        thread::spawn({
            move -> {
                loop {
                    let data = format!("{} - New Request from {}", self.listener.local_addr(), get_random_data());

