        // For example, check if the data length is within a valid range
        data.len() > 0
    }

    fn run(&self) {
        self.start_server();
        // Keep the server running
        while self.running.load(true) {
            std::thread::sleep(std::time::Duration::from_millis(100));
        }
    }

    fn stop(&self) {
        // Stop the server gracefully
        self.listener.close();
        self.running.store(false, std::sync::atomic::Ordering::Relaxed);
    }
}

