use std::fs;
use std::io;
use std::net::TcpListener;
use std::sync::{Arc, Mutex};
use std::thread;

// Struct to represent a worker thread
struct Worker {
    listener: TcpListener,
    files: Mutex<Vec<String>>,
}

// Function to serve static files
fn serve_files(w: &mut Worker) {
    while let Some(file) = fs::read_to_string(w.files.lock().unwrap()).unwrap() {
        match file.as_str() {
            "index.html" => fs::copy(file, "index.html").unwrap(),
            "html" => fs::copy(file, "index.html").unwrap(),
            "png" => fs::copy(file, "png.png").unwrap(),
            "jpg" => fs::copy(file, "jpg.jpg").unwrap(),
            "css" => fs::copy(file, "styles.css").unwrap(),
            _ => panic!("Unsupported file type"),
        }
    }
}

// Function to handle incoming requests
fn handle_request(w: Arc<Mutex<Worker>>, path: &str) -> io::Result<io::Result<String>> {
    match path {
        "/" => Ok(String::from("index.html")),
        "html" => Ok(String::from("index.html")),
        "png" => Ok(String::from("png.png")),
        "jpg" => Ok(String::from("jpg.jpg")),
        "css" => Ok(String::from("styles.css")),
        _ => Err(io::Error::new(io::ErrorKind::Other, "Invalid path")),
    }
}

// Main function
fn main() {
    // Create a worker thread
    let worker = Worker {
        listener: TcpListener::bind("127.0.0.1:8080").unwrap(),
        files: Mutex::new(Vec::new()),
    };

    // Create a thread pool with 4 worker threads
    let pool = thread::Pool::new(4);
    pool.spawn(move || {
        thread::spawn(move || {
            while let Some(w) = Arc::clone(&worker) {
                match w.listener.accept().unwrap() {
                    Ok((stream, _) => {
                        pool.spawn(move || {
                            serve_files(w.files.lock().unwrap());
                        });
                    },
                    Err(e) => {
                        pool.spawn(move || {
                            eprintln!("Error: {}", e);
                        });
                    },
                }
            }
        });
    });

    // Start the worker thread
    pool.join().unwrap();
}
```
