    if parts.len() < 2 { return None; }
    let file_extension = &parts[1..].join("/");
    if file_extension == "html" { return Some("html"); }
    if file_extension == "png" || file_extension == "jpg" || file_extension == "css" { return Some(file_extension.split(".").last().unwrap()); }
    None
}

fn get_filename_from_extension(extension: &str) -> Option<&str> {
    if extension == "html" { return Some("index.html"); }
    if extension == "png" { return Some("image.png"); }
    if extension == "jpg" { return Some("image.jpg"); }
    if extension == "css" { return Some("styles.css"); }
    None
}

fn read_file(filename: &str) -> Result<String, std::io::Error> {
    let file = File::open(filename)?;
    let mut content = String::new();
    let mut buffer = Vec::new();

    let reader = Read::new(&file)?;
    buffer.extend(reader);
    content = buffer.join("");
    Ok(content)
}

fn get_extension_from_filename(filename: &str) -> Option<&str> {
    read_file(filename)?.get_extension_from_filename();
}

fn get_filename_from_extension(extension: &str) -> Option<&str> {
    read_file(filename)?.get_filename_from_extension();
}

#[derive(Debug)]
struct Response {
    status: u16,
    headers: Vec<(&str, &str)>>,
    body: String,
}

fn response(status: u16, headers: Vec<(&str, &str)>>, body: String) -> Response {
    Response {
        status,
        headers,
        body,
    }
}

fn handle_request(mut stream: TcpStream, listener: Arc<Mutex<TcpListener>>)) -> Result<(), Error> {
    let mut request = Request::new();

    let (mut request_header, mut request_body) = stream.read_until('\r'.to_string());

    request_header = request_header.split_whitespace().collect::<Vec<_>>();
    request_body = request_body.split_whitespace().collect::<Vec<_>>();

    request.set_header(&mut request_header);
    request.set_body(&mut request_body);

    let file_extension = get_extension_from_filename(&request.get_path());
    if let Some(extension) = file_extension {
