fn main() -> Result<(), Error> {
    let listener = Arc::new(Mutex::new(TcpListener::new().unwrap()));
    listener.lock().unwrap().listen(8080)?;

    let mut stream = TcpStream::new().unwrap();
    let response = handle_request(stream, listener.clone())?;
    println!("{:?}", response);

