**src/main.rs**
```rust
use std::fs::File;
use std::io::{Read, Seek, SeekFrom, Write};
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::sync::mpsc;
use tokio::sync::Arc;

const PORT: u16 = 8080;
const NUM_WORKERS: usize = 4;

async fn handle_request(req: tokio::net::TcpStream) {
    let mut file = File::open(req.peer().unwrap()).await.unwrap();
    let mut buffer = [0u8; 1024];

    loop {
        let read = async_std::io::copy(file, buffer.as_mut_ptr(), buffer.len()).await.unwrap();
        if read == 0 {
            break;
        }

        let content = std::str::from_utf8(&buffer[..read]).unwrap();
        let headers = req.headers().clone();

        match content {
            "GET" => {
                let path = req.peer().unwrap().as_ref().unwrap().path().to_str().unwrap();
                let path = path.to_string_lossy().into_owned();

                if path == "index.html" || path == "html" || path == "png" || path == "jpg" || path == "css" {
                    req Peer().unwrap().write_all(format!("HTTP/1.1 200 OK\r\n\r\n{}", path.as_ref()).as_bytes()).await.unwrap();
                } else {
                    req Peer().unwrap().write_all(content.as_bytes()).await.unwrap();
                }
            }
            _ => {
                req Peer().unwrap().write_all(content.as_bytes()).await.unwrap();
            }
        }
    }

    req Peer().unwrap().shutdown().unwrap();
}

async fn main() {
    tokio::spawn(async move {
        let (tx, rx) = mpsc::channel();

